-- J-LAS Flashcard: hoạt động MÔ PHỎNG cho bộ giáo trình (lượt học, số sao, yêu thích), MySQL 8.0.16+, UTF-8.
-- GENERATED by tools/flashcard_textbook/build_activity.py. Do not edit.
-- SYNTHETIC DEMO DATA: {{LEARNER_COUNT}} học viên mẫu hư cấu (tools/demo_learners.py, tạo bởi seed Shadowing), không phải người dùng
-- hay đánh giá thật. Chỉ dùng dev/demo; KHÔNG chạy trên production.
-- {{SET_COUNT}} bộ / {{STATE_COUNT}} lượt người học-bộ / {{RATING_COUNT}} đánh giá / {{FAVORITE_COUNT}} yêu thích / {{SESSION_COUNT}} lượt học xong.
-- Chạy sau seed_data_flashcard_textbook.sql. Bộ mới tạo (dưới 30 ngày) được lùi ngày tạo 60 ngày, giữ nguyên thứ tự,
-- để hoạt động có chỗ trải ra. Chạy lại an toàn: học viên đã có trạng thái với bộ thì giữ nguyên, lượt học có mã riêng.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;

DROP TEMPORARY TABLE IF EXISTS fca_set;
DROP TEMPORARY TABLE IF EXISTS fca_learner;
DROP TEMPORARY TABLE IF EXISTS fca_state;
DROP TEMPORARY TABLE IF EXISTS fca_session;
CREATE TEMPORARY TABLE fca_set (
    set_key VARCHAR(60) NOT NULL PRIMARY KEY, kind VARCHAR(10) NOT NULL, title VARCHAR(100) NOT NULL,
    set_id BIGINT UNSIGNED NULL, created_at DATETIME(6) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TEMPORARY TABLE fca_learner (
    email VARCHAR(255) NOT NULL PRIMARY KEY, user_id BIGINT UNSIGNED NULL, created_at DATETIME(6) NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TEMPORARY TABLE fca_state (
    set_key VARCHAR(60) NOT NULL, email VARCHAR(255) NOT NULL, rating TINYINT UNSIGNED NULL, favorite TINYINT NOT NULL,
    first_permille SMALLINT UNSIGNED NOT NULL, last_permille SMALLINT UNSIGNED NOT NULL, PRIMARY KEY (set_key, email)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TEMPORARY TABLE fca_session (
    set_key VARCHAR(60) NOT NULL, email VARCHAR(255) NOT NULL, request_id VARCHAR(36) NOT NULL,
    permille SMALLINT UNSIGNED NOT NULL, seconds INT UNSIGNED NOT NULL, PRIMARY KEY (request_id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

{{DATA}}

DROP PROCEDURE IF EXISTS jlas_seed_flashcard_textbook_activity_v1;
DELIMITER $$
CREATE PROCEDURE jlas_seed_flashcard_textbook_activity_v1()
SQL SECURITY INVOKER
BEGIN
    DECLARE started INT DEFAULT 0;
    DECLARE anchor DATETIME(6);
    DECLARE learners INT DEFAULT 0;
    DECLARE sets_found INT DEFAULT 0;
    DECLARE states_before INT DEFAULT 0;
    DECLARE sessions_before INT DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        IF started = 1 THEN ROLLBACK; END IF;
        RESIGNAL;
    END;
    IF DATABASE() IS NULL OR @@autocommit <> 1 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Select a DEMO database in a fresh autocommit connection';
    END IF;
    SET anchor = CURRENT_TIMESTAMP(6) - INTERVAL 1 HOUR;

    -- Chỉ nhận tài khoản học viên mẫu (không mật khẩu, không Google, chưa xác minh); không bao giờ dùng tài khoản thật.
    UPDATE fca_learner l JOIN users u ON u.email = l.email
    SET l.user_id = u.id, l.created_at = u.created_at
    WHERE u.password_hash IS NULL AND u.google_id IS NULL AND u.is_verified = 0 AND u.login_type = 'LOCAL';
    SELECT COUNT(user_id) INTO learners FROM fca_learner;
    IF learners = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'Demo learners not found; run the Shadowing interaction seed first';
    END IF;

    START TRANSACTION;
    SET started = 1;
    UPDATE fca_set d SET d.set_id = (
        SELECT MIN(s.id) FROM flashcard_set s
        WHERE s.deleted_at IS NULL AND s.visibility = 'PUBLIC'
          AND IF(d.kind = 'TEXTBOOK', s.moderation_summary = CONCAT('TEXTBOOK_FLASHCARD:', d.set_key),
                 s.title = d.title COLLATE utf8mb4_bin));
    UPDATE flashcard_set s JOIN fca_set d ON d.set_id = s.id
    SET s.updated_at = s.created_at - INTERVAL 60 DAY, s.created_at = s.created_at - INTERVAL 60 DAY
    WHERE s.created_at > anchor - INTERVAL 30 DAY;
    UPDATE fca_set d JOIN flashcard_set s ON s.id = d.set_id SET d.created_at = s.created_at;
    SELECT COUNT(set_id) INTO sets_found FROM fca_set;
    SELECT COUNT(*) INTO states_before FROM flashcard_user_set_state;
    SELECT COUNT(*) INTO sessions_before FROM flashcard_study_session;

    -- Mỗi mốc là permille của khoảng [sau ngày tạo bộ và tài khoản + 1 ngày, lúc chạy - 1 giờ].
    INSERT IGNORE INTO flashcard_user_set_state (user_id, set_id, is_favorite, rating, first_completed_at,
                                                 last_accessed_at, updated_at)
    SELECT l.user_id, d.set_id, x.favorite, x.rating,
           TIMESTAMPADD(SECOND, TIMESTAMPDIFF(SECOND, GREATEST(d.created_at, l.created_at + INTERVAL 1 DAY), anchor)
                                * x.first_permille DIV 1000, GREATEST(d.created_at, l.created_at + INTERVAL 1 DAY)),
           TIMESTAMPADD(SECOND, TIMESTAMPDIFF(SECOND, GREATEST(d.created_at, l.created_at + INTERVAL 1 DAY), anchor)
                                * x.last_permille DIV 1000, GREATEST(d.created_at, l.created_at + INTERVAL 1 DAY)),
           anchor
    FROM fca_state x
        JOIN fca_set d ON d.set_key = x.set_key AND d.set_id IS NOT NULL
        JOIN fca_learner l ON l.email = x.email AND l.user_id IS NOT NULL
    WHERE GREATEST(d.created_at, l.created_at + INTERVAL 1 DAY) < anchor;
    INSERT IGNORE INTO flashcard_study_session (user_id, set_id, session_type, creation_request_id, mode, status,
                                                started_at, finished_at)
    SELECT l.user_id, d.set_id, 'FLASHCARD', x.request_id, 'ALL', 'COMPLETED',
           TIMESTAMPADD(SECOND, TIMESTAMPDIFF(SECOND, GREATEST(d.created_at, l.created_at + INTERVAL 1 DAY), anchor)
                                * x.permille DIV 1000, GREATEST(d.created_at, l.created_at + INTERVAL 1 DAY)),
           TIMESTAMPADD(SECOND, TIMESTAMPDIFF(SECOND, GREATEST(d.created_at, l.created_at + INTERVAL 1 DAY), anchor)
                                * x.permille DIV 1000 + x.seconds, GREATEST(d.created_at, l.created_at + INTERVAL 1 DAY))
    FROM fca_session x
        JOIN fca_set d ON d.set_key = x.set_key AND d.set_id IS NOT NULL
        JOIN fca_learner l ON l.email = x.email AND l.user_id IS NOT NULL
    WHERE GREATEST(d.created_at, l.created_at + INTERVAL 1 DAY) < anchor
    ORDER BY 7;
    COMMIT;
    SET started = 0;
    SELECT 'SYNTHETIC_DEMO' AS data_kind, learners AS demo_learners, sets_found AS sets_found,
           (SELECT COUNT(*) FROM flashcard_user_set_state) - states_before AS states_added,
           (SELECT COUNT(*) FROM flashcard_study_session) - sessions_before AS sessions_added;
END$$
DELIMITER ;

CALL jlas_seed_flashcard_textbook_activity_v1();
DROP PROCEDURE IF EXISTS jlas_seed_flashcard_textbook_activity_v1;
DROP TEMPORARY TABLE IF EXISTS fca_set;
DROP TEMPORARY TABLE IF EXISTS fca_learner;
DROP TEMPORARY TABLE IF EXISTS fca_state;
DROP TEMPORARY TABLE IF EXISTS fca_session;
